def build():
    seen = set()
    for row in ENTRIES:
        if row["status"] not in ALLOWED:
            raise ValueError(f"invalid status: {row['status']}")
        key = (row["native_file"], row["native_function"])
        if key in seen:
            raise ValueError(f"duplicate inventory key: {key}")
        seen.add(key)
        source = NATIVE / row["native_file"]
        if not source.is_file():
            raise FileNotFoundError(source)
        if row["native_function"] not in source.read_text(encoding="utf-8", errors="replace"):
            raise ValueError(f"native function not found: {key}")
    return ENTRIES


def main():
    rows = build()
    OUTPUT.write_text("".join(json.dumps(r, sort_keys=True) + "\n" for r in rows), encoding="utf-8")
    counts = Counter(r["status"] for r in rows)
    status = {
        "schema_version": 1,
        "pinned_commit": "726522be4e2a13454d8415b7ef799d621f665cf3",
        "scope": "Numerical solver and iterative scientific-model families; source symbols are tracked separately.",
        "allowed_statuses": sorted(ALLOWED),
        "counts": dict(sorted(counts.items())),
        "complete": False,
        "completion_rule": "Only exact-pinned differential evidence can promote PARTIAL/APPROXIMATE/NOT_IMPLEMENTED.",
        "inventory": "audit/complete_solver_inventory.jsonl",
        "subsystems": [{"subsystem": r["subsystem"], "status": r["status"],
                        "evidence": r["validation_test"] or None} for r in rows],
    }
    STATUS_OUTPUT.write_text(json.dumps(status, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({"entries": len(rows), "counts": counts, "complete": False}))


if __name__ == "__main__":
    main()
